// ArrayBuffer.prototype.transfer / transferToFixedLength / detached (T47).
const t = (f) => { try { console.log(f()); } catch (e) { console.log(e.constructor.name + ": " + e.message); } };
const rab = new ArrayBuffer(6, { maxByteLength: 8 });
const lt = new Uint8Array(rab);
lt.set([1, 2, 3, 4, 5, 6]);
const fl = new Uint16Array(rab, 2, 2);
const moved = rab.transfer();
console.log(moved, rab, rab.detached, rab.byteLength, rab.maxByteLength, rab.resizable, moved.resizable, moved.maxByteLength);
console.log(lt, lt.length, lt.byteLength, lt.byteOffset, fl.length, lt[0], 0 in lt);
lt[0] = 9;
console.log(lt[0], Object.keys(lt), { rab });
t(() => rab.transfer());
t(() => rab.transferToFixedLength());
t(() => rab.resize(1));
t(() => rab.slice());
t(() => new Uint8Array(rab));
t(() => new Uint8Array(rab, 0, 0));
t(() => new Uint8Array(lt));
t(() => lt.fill(0));
t(() => lt.values());
t(() => lt.subarray(0));
const fixed = moved.transferToFixedLength(3);
console.log(fixed, fixed.resizable, moved.detached);
const longer = fixed.transfer(5);
console.log(longer, longer.resizable, fixed.detached);
const again = new ArrayBuffer(4, { maxByteLength: 6 });
t(() => again.transfer(7));
t(() => again.transfer(-1));
const grown = again.transfer(6);
console.log(grown, grown.maxByteLength, again.detached);
t(() => ArrayBuffer.prototype.transfer.call(1));
t(() => ArrayBuffer.prototype.transferToFixedLength.call({}));
t(() => Object.getOwnPropertyDescriptor(ArrayBuffer.prototype, "detached").get.call(1));
const plain = new ArrayBuffer(2);
const view = new Int8Array(plain);
view[1] = -1;
const out = plain.transfer();
console.log(plain.detached, new Int8Array(out), view, view.length);
const it = new Int8Array(out).values();
out.transfer(1);
t(() => it.next());
t(() => [...view]);
t(() => view.join());
